const MAX_PER_RUN = 5;

const rows = $input.all();
const selected = rows
  .filter(item => String(item.json.status ?? '').trim().toUpperCase() === 'NEW')
  .filter(item => String(item.json.website ?? '').trim() !== '')
  .slice(0, MAX_PER_RUN);

return selected.map(item => {
  const r = item.json;

  if (r.row_number === undefined || r.row_number === null || r.row_number === '') {
    throw new Error('Google Sheets non ha restituito row_number. Controlla che la prima riga del foglio contenga le intestazioni.');
  }

  let website = String(r.website ?? '').trim();
  if (website && !/^https?:\/\//i.test(website)) {
    website = 'https://' + website;
  }

  return {
    json: {
      name: String(r.name ?? '').trim(),
      company: String(r.company ?? '').trim(),
      role: String(r.role ?? '').trim(),
      linkedin_notes: String(r.linkedin_notes ?? '').trim(),
      website,
      status: 'PROCESSING',
      score: r.score ?? '',
      reason: String(r.reason ?? ''),
      pain: String(r.pain ?? ''),
      opening: String(r.opening ?? ''),
      dm: String(r.dm ?? ''),
      error: '',
      processed_at: String(r.processed_at ?? ''),
      row_number: r.row_number,
    }
  };
});

