// Recupera il prospect che ha generato questa chiamata HTTP.
const prospect = $('Mark PROCESSING').item.json;
const raw = $json;

// L'endpoint Apify può restituire un array di pagine oppure un oggetto.
let pages = [];
if (Array.isArray(raw)) {
  pages = raw;
} else if (raw && Array.isArray(raw.body)) {
  pages = raw.body;
} else if (raw && typeof raw === 'object') {
  // Alcune versioni/risposte di n8n trasformano un array JSON in un oggetto indicizzato.
  const numericValues = Object.keys(raw)
    .filter(k => /^\d+$/.test(k))
    .sort((a,b) => Number(a) - Number(b))
    .map(k => raw[k]);
  pages = numericValues.length ? numericValues : [raw];
}

const chunks = [];
const sources = [];

for (const page of pages) {
  if (!page || typeof page !== 'object') continue;

  const url = String(page.url ?? page.loadedUrl ?? '').trim();
  const title = String(page.title ?? '').trim();

  let content =
    page.markdown ??
    page.text ??
    page.content ??
    page.pageFunctionResult?.markdown ??
    page.pageFunctionResult?.text ??
    '';

  content = String(content ?? '')
    .replace(/\u0000/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{4,}/g, '\n\n\n')
    .trim();

  if (!content) continue;

  if (url) sources.push(url);
  chunks.push(
    `${title ? `# ${title}\n` : ''}${url ? `SOURCE: ${url}\n` : ''}${content}`
  );
}

// 18k caratteri sono più che sufficienti per questa qualificazione e tengono basso il costo.
const websiteText = chunks.join('\n\n---\n\n').slice(0, 18000);
const scrapeOk = websiteText.length >= 200;

return [{
  json: {
    name: prospect.name,
    company: prospect.company,
    role: prospect.role,
    linkedin_notes: prospect.linkedin_notes,
    website: prospect.website,
    row_number: prospect.row_number,
    website_text: websiteText || '[Contenuto del sito non disponibile]',
    sources: [...new Set(sources)].slice(0, 5),
    scrape_ok: scrapeOk,
  }
}];

