const prospect = $('Build AI Input').item.json;
const response = $json;

function getText(resp) {
  if (!resp) return '';
  if (typeof resp.output_text === 'string') return resp.output_text;

  if (Array.isArray(resp.output)) {
    for (const outputItem of resp.output) {
      if (!Array.isArray(outputItem?.content)) continue;
      for (const part of outputItem.content) {
        if (typeof part?.text === 'string') return part.text;
      }
    }
  }

  // Se l'HTTP Request è configurato per includere la risposta completa.
  if (resp.body) return getText(resp.body);
  return '';
}

let status = 'READY';
let error = '';
let ai = {};

try {
  const text = getText(response);
  if (!text) {
    throw new Error(response?.message || response?.error?.message || 'OpenAI non ha restituito testo strutturato');
  }

  ai = typeof text === 'string' ? JSON.parse(text) : text;
} catch (e) {
  status = 'ERROR';
  error = String(e?.message || e).slice(0, 500);
}

let score = Number(ai.score);
if (!Number.isFinite(score)) score = 1;
score = Math.max(1, Math.min(10, Math.round(score)));

let dm = String(ai.dm ?? '').trim();
if (dm.length > 320) dm = dm.slice(0, 317).trimEnd() + '...';

return [{
  json: {
    name: prospect.name,
    company: prospect.company,
    role: prospect.role,
    linkedin_notes: prospect.linkedin_notes,
    website: prospect.website,
    status,
    score: status === 'READY' ? score : '',
    reason: status === 'READY' ? String(ai.reason ?? '').trim() : '',
    pain: status === 'READY' ? String(ai.pain ?? '').trim() : '',
    opening: status === 'READY' ? String(ai.opening ?? '').trim() : '',
    dm: status === 'READY' ? dm : '',
    error,
    processed_at: new Date().toISOString(),
    row_number: prospect.row_number,
  }
}];
